(()=>{let prompt;const btn=document.getElementById('installNow'),status=document.getElementById('offlineStatus');document.getElementById('installHelp').onclick=()=>{document.getElementById('installDialog').showModal();if(matchMedia('(display-mode: standalone)').matches||navigator.standalone)document.getElementById('installIntro').textContent='你正在桌面版小晴岛中。也可以把二维码分享给同学。'};window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();prompt=e;btn.hidden=false});btn.onclick=async()=>{if(!prompt)return;await prompt.prompt();await prompt.userChoice;prompt=null;btn.hidden=true};window.addEventListener('appinstalled',()=>{btn.hidden=true;document.getElementById('installIntro').textContent='已添加到桌面，欢迎常来。'});if('serviceWorker' in navigator&&/^https?:$/.test(location.protocol)){navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;status.textContent='离线内容已准备好，下次断网也能打开。'}).catch(()=>status.textContent='离线内容暂未准备好，请联网刷新后重试。');}else status.textContent='请通过网站链接打开，以准备桌面安装和离线内容。';})();